SELECT 'offer_v3_avyron_legal202611',t.id,3,'{"title":"Ofertă comercială și deviz","header":"AVYRON · {{provider.legal_name}}","footer":"{{provider.contact_email}} · Document privat · {{beneficiary.legal_name}}","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Vă propunem o soluție construită în jurul activității dumneavoastră. Oferta separă rezultatul urmărit, livrabilele, investiția și pașii de lucru, pentru a putea decide în cunoștință de cauză."}]},{"type":"paragraph","content":[{"type":"text","text":"TRASEU AVYRON · ETAPA 2/5 · Se confirmă pachetul, costurile și versiunea acceptată."}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate: {{scope}}. Data: {{date}}."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Emitent AVYRON"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Beneficiar / destinatar"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{provider.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"CUI {{provider.tax_id}} · ONRC {{provider.registration_number}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate / corespondență: {{provider.address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Sediu social: {{provider.registered_address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Capital social: {{provider.share_capital}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Contact: {{provider.contact_email}}"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.summary}}"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Calitatea beneficiarului în această relație: {{contract_capacity}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"01 Contextul și direcția propusă"}]},{"type":"paragraph","content":[{"type":"text","text":"Am organizat propunerea pentru {{scope}}, pornind de la următoarele obiective: {{objectives}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Soluția propusă: {{solution}}. Varianta comercială: {{offer_variant}}. Beneficiile urmărite sunt obiective ale colaborării; poziționările, vânzările și rezultatele dependente de terți nu sunt garantate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"02 Ce primește beneficiarul"}]},{"type":"paragraph","content":[{"type":"text","text":"Livrabilele, formatele și limitele asumate: {{deliverables}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Opțiunile incluse: {{inclusions}}. Fiecare serviciu sau produs este individualizat în deviz și în detaliile activității, fără extinderea implicită la alte proiecte."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"03 Cum lucrăm și ce avem nevoie"}]},{"type":"paragraph","content":[{"type":"text","text":"Calendarul estimativ și punctele de verificare: {{schedule}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Materialele, accesurile, responsabilii și aprobările necesare: {{dependencies}}. Modificările de scop se evaluează și se confirmă înainte de executare, împreună cu impactul asupra costurilor și termenelor."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"04 Investiția și costurile separate"}]},{"type":"paragraph","content":[{"type":"text","text":"Devizul de la final distinge valoarea de catalog de valoarea ofertată și arată cantitatea, taxele și recurența fiecărei poziții. Orice reducere sau majorare este justificată și se aplică exclusiv acestei oferte."}]},{"type":"paragraph","content":[{"type":"text","text":"Elementele excluse și costurile furnizorilor externi: {{exclusions}}. Domeniile, bugetele media, licențele și abonamentele terților nu se confundă cu onorariul AVYRON. Regimul fiscal aplicabil: {{tax_regime}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Durata și condițiile costurilor recurente: {{duration}}. Sumele unice și cele periodice se citesc separat; variantele alternative se confirmă înainte de acceptare."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"05 Plata și valabilitatea"}]},{"type":"paragraph","content":[{"type":"text","text":"Condițiile de plată, eventualul avans și scadențele: {{payment_terms}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Oferta este valabilă până la {{valid_until}}. Un câmp necompletat nu introduce un tarif, o durată sau o autorizare de debitare. Factura fiscală se emite prin fluxul de facturare aplicabil, separat de prezenta ofertă."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Opțiuni suplimentare"}]},{"type":"paragraph","content":[{"type":"text","text":"Propuneri care pot completa proiectul: {{optional_extras}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Aceste opțiuni sunt prezentate pentru analiză, fără obligație de achiziție. Nu intră în totalul ofertei și nu se execută fără acceptarea separată a conținutului, prețului și condițiilor lor."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"06 Acceptare și pasul următor"}]},{"type":"paragraph","content":[{"type":"text","text":"Pentru continuare se confirmă versiunea ofertei, pachetul ales și condițiile de acceptare: {{acceptance}}. Modalitatea de confirmare este {{acceptance_method}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Contact AVYRON: {{provider.contact_email}}. Confirmarea aparține persoanelor autorizate să reprezinte beneficiarul; semnăturile se colectează prin canalul convenit, dacă sunt necesare. Oferta nu transferă singură drepturi asupra codului sau creațiilor și nu înlocuiește acordurile contractuale care trebuie încheiate separat."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Condiții specifice și repere de aplicare"}]},{"type":"paragraph","content":[{"type":"text","text":"Informațiile de identificare și capitalul social se completează conform art. 74 din Legea nr. 31/1990. Prețurile, taxele, recurențele și costurile terților sunt prezentate distinct, în acord cu informarea prevăzută la art. 5 din Legea nr. 365/2002. Acceptarea identifică versiunea și opțiunea aleasă; nu se prezumă o comandă din simpla vizualizare a ofertei."}]}]},"fields":{},"labels":{"__avyron_design":"2026","__avyron_edition":"2026-11","__avyron_stage":"2/5","__avyron_legal_review":"2026-11-10"},"lines":[]}','["date","provider.legal_name","provider.tax_id","provider.registration_number","provider.address","provider.registered_address","provider.share_capital","beneficiary.legal_name","scope","objectives","deliverables","schedule","payment_terms","valid_until","exclusions","contract_capacity"]','review_required',CAST(strftime('%s','now') AS INTEGER)*1000
FROM document_templates t JOIN document_template_versions v ON v.template_id=t.id AND v.id='offer_v2_avyron2026' AND v.version=2 AND v.review_status<>'retired'
