SELECT 'framework_v3_avyron_legal202611',t.id,3,'{"title":"Contract-cadru","header":"AVYRON · {{provider.legal_name}}","footer":"{{provider.contact_email}} · Document privat · {{beneficiary.legal_name}}","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Acest contract stabilește cadrul colaborării, responsabilitățile părților și condițiile în care serviciile sunt comandate, verificate și predate. Anexele acceptate individualizează fiecare activitate."}]},{"type":"paragraph","content":[{"type":"text","text":"TRASEU AVYRON · ETAPA 3/5 · Semnatarii verifică natura relației, anexele și clauzele speciale."}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate: {{scope}}. Data: {{date}}."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Emitent AVYRON"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Beneficiar / destinatar"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{provider.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"CUI {{provider.tax_id}} · ONRC {{provider.registration_number}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate / corespondență: {{provider.address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Sediu social: {{provider.registered_address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Capital social: {{provider.share_capital}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Contact: {{provider.contact_email}}"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.summary}}"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Calitatea beneficiarului în această relație: {{contract_capacity}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Identificarea juridică a beneficiarului: {{beneficiary.identification}}. Sunt utilizate numai datele necesare relației documentate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 1. Părțile și natura relației"}]},{"type":"paragraph","content":[{"type":"text","text":"{{provider.legal_name}}, identificată în fișa părților, cu adresa de activitate și corespondență {{provider.address}}, și {{beneficiary.legal_name}}, forma {{beneficiary.entity_type}}, cu sediul/adresa în {{beneficiary.address}}, convin prezentul contract prin reprezentanții {{signatories}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Relația juridică avută în vedere este {{relationship_type}}. Pentru parteneriate, colaborare independentă, subcontractare ori alte raporturi, dispozițiile specifice se verifică și se adaptează înainte de aprobare; titulatura documentului nu stabilește singură natura juridică."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 2. Obiectul și documentele aplicabile"}]},{"type":"paragraph","content":[{"type":"text","text":"Obiectul convenit este {{scope}}. Livrabilele, limitele, etapele și criteriile măsurabile sunt stabilite în anexele acceptate: {{deliverables}}. În caz de neconcordanță, ordinea de prioritate convenită este {{document_priority}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Orice extindere de scop, tarif sau calendar se confirmă de persoanele autorizate înainte de executare. Solicitările și discuțiile tehnice nu modifică singure contractul."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 3. Executarea și obligațiile părților"}]},{"type":"paragraph","content":[{"type":"text","text":"AVYRON execută activitățile convenite cu diligență profesională, documentează livrarea și comunică impedimentele cunoscute. Beneficiarul furnizează informații corecte, materiale utilizabile legal, accesuri limitate și aprobări prin responsabilii desemnați."}]},{"type":"paragraph","content":[{"type":"text","text":"Calendarul și dependențele sunt {{schedule}} și {{dependencies}}. Întârzierile determinate de neîndeplinirea unei dependențe se analizează și se reflectă într-un calendar actualizat confirmat de părți."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 4. Preț, facturare și plată"}]},{"type":"paragraph","content":[{"type":"text","text":"Prețurile și moneda rezultă din anexele și devizele acceptate. Condițiile de plată sunt {{payment_terms}}, iar regimul fiscal confirmat este {{tax_regime}}. Costurile terților și bugetele media se suportă numai potrivit acordului expres."}]},{"type":"paragraph","content":[{"type":"text","text":"Recurențele, ajustările și condițiile de suspendare pentru neplată sunt {{recurring_terms}}. Nicio penalitate, reînnoire ori autorizare de debitare nu rezultă dintr-un câmp necompletat."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 5. Livrare și acceptanță"}]},{"type":"paragraph","content":[{"type":"text","text":"Livrarea se notifică prin canalul convenit și este însoțită de informațiile necesare verificării. Procedura, criteriile și termenul de verificare sunt {{acceptance}}. Observațiile trebuie să indice neconformitățile raportate la scopul acceptat."}]},{"type":"paragraph","content":[{"type":"text","text":"Remedierea defectelor din scop se distinge de funcționalitățile noi. Acceptarea tacită, dacă este dorită, necesită o clauză expresă verificată juridic; simpla transmitere a fișierelor nu o instituie."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 6. Proprietate intelectuală și servicii externe"}]},{"type":"paragraph","content":[{"type":"text","text":"Drepturile transferate sau licențiate, momentul producerii efectelor și excluderile sunt {{ip_terms}}. Componentele preexistente, instrumentele AVYRON și operele terților păstrează regimul de licență aplicabil."}]},{"type":"paragraph","content":[{"type":"text","text":"Accesul la un produs, abonament sau fișier nu transferă implicit codul-sursă ori drepturi exclusive. Beneficiarul răspunde pentru drepturile materialelor furnizate. Condițiile platformelor externe se aplică separat și nu pot fi garantate de AVYRON."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 7. Confidențialitate și date"}]},{"type":"paragraph","content":[{"type":"text","text":"Părțile limitează accesul la informațiile confidențiale la persoanele care au nevoie de ele pentru executare și aplică măsuri adecvate de protecție. Excepțiile, durata și obligațiile speciale sunt {{confidentiality_terms}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Rolurile privind datele personale se stabilesc potrivit operațiunilor efective. Dacă este necesară prelucrarea în numele beneficiarului, părțile aprobă un acord distinct cu instrucțiunile și anexele relevante; acesta nu se presupune încheiat automat."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 8. Răspundere, încetare și litigii"}]},{"type":"paragraph","content":[{"type":"text","text":"Regimul răspunderii și limitele negociate sunt {{liability_terms}}, cu respectarea dispozițiilor imperative aplicabile. Evenimentele neimputabile și procedura de notificare sunt {{force_majeure_terms}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Durata, denunțarea, rezilierea, efectele încetării și predarea sunt {{termination_terms}}. Soluționarea disputelor și legea aplicabilă sunt {{governing_terms}}. Modificările se consemnează în scris de reprezentanții autorizați."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Condiții specifice și repere de aplicare"}]},{"type":"paragraph","content":[{"type":"text","text":"Cadrul urmează art. 1170, 1176 și 1270 Cod civil. Clauzele standard neuzuale din sfera art. 1203, inclusiv anumite limitări, reînnoiri sau derogări de competență, se evidențiază și se acceptă expres în scris când norma le cere; nu rezultă dintr-o bifă preselectată."}]},{"type":"paragraph","content":[{"type":"text","text":"Pentru creațiile comandate, cesiunea sau licența se individualizează: drepturi, utilizări, teritoriu, durată, exclusivitate și remunerație. Se verifică art. 42–43 din Legea nr. 8/1996, republicată. Resursele preexistente și licențele terților sunt inventariate separat, fără a promite drepturi pe care AVYRON nu le deține."}]}]},"fields":{},"labels":{"__avyron_design":"2026","__avyron_edition":"2026-11","__avyron_stage":"3/5","__avyron_legal_review":"2026-11-10"},"lines":[]}','["date","provider.legal_name","provider.tax_id","provider.registration_number","provider.address","provider.registered_address","provider.share_capital","beneficiary.legal_name","scope","beneficiary.entity_type","beneficiary.identification","beneficiary.address","signatories","deliverables","schedule","payment_terms","ip_terms","liability_terms","termination_terms","governing_terms","relationship_type","contract_capacity"]','review_required',CAST(strftime('%s','now') AS INTEGER)*1000
