SELECT 'annex_v3_avyron_legal202611',t.id,3,'{"title":"Anexă de servicii","header":"AVYRON · {{provider.legal_name}}","footer":"{{provider.contact_email}} · Document privat · {{beneficiary.legal_name}}","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Această anexă transformă propunerea acceptată într-un perimetru de lucru verificabil: ce se livrează, în ce condiții, cu ce limite și după ce criterii se confirmă finalizarea."}]},{"type":"paragraph","content":[{"type":"text","text":"TRASEU AVYRON · ETAPA 3/5 · Fiecare serviciu are limite, probă de livrare și cost propriu."}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate: {{scope}}. Data: {{date}}."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Emitent AVYRON"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Beneficiar / destinatar"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{provider.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"CUI {{provider.tax_id}} · ONRC {{provider.registration_number}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate / corespondență: {{provider.address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Sediu social: {{provider.registered_address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Capital social: {{provider.share_capital}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Contact: {{provider.contact_email}}"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.summary}}"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Calitatea beneficiarului în această relație: {{contract_capacity}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Identificarea juridică a beneficiarului: {{beneficiary.identification}}. Sunt utilizate numai datele necesare relației documentate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 1. Legătura cu acordul principal"}]},{"type":"paragraph","content":[{"type":"text","text":"Prezenta anexă aparține acordului {{contract_reference}} și descrie {{scope}} pentru {{beneficiary.legal_name}}. Documentul identifică proiectele și instanțele de servicii cărora li se aplică; nu extinde acordul asupra altor beneficiari."}]},{"type":"paragraph","content":[{"type":"text","text":"Dacă sunt incluse mai multe servicii, limitele, livrabilele și costurile se individualizează pentru fiecare. Ordinea de prioritate între documente rămâne cea convenită în acordul principal."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 2. Livrabile și limite"}]},{"type":"paragraph","content":[{"type":"text","text":"Livrabilele contractate și formatele de predare sunt {{deliverables}}. Funcționalitățile, cantitățile, paginile, platformele, integrările și intervențiile incluse sunt {{requirements}}. Excluderile explicite sunt {{exclusions}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Lucrările suplimentare și reviziile care depășesc aceste limite necesită confirmarea impactului asupra costurilor și calendarului. Bugetele media, licențele, domeniile și taxele terților nu se confundă cu onorariul de implementare."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 3. Organizare și dependențe"}]},{"type":"paragraph","content":[{"type":"text","text":"Calendarul și punctele de aprobare sunt {{schedule}}. Materialele, accesurile și deciziile datorate de fiecare parte sunt {{dependencies}}. Responsabilii operaționali și canalele de comunicare: {{contacts}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Dependențele externe și condițiile tehnice de funcționare sunt {{technical_conditions}}. O integrare indisponibilă nu este prezentată ca activă; alternativele se aprobă înainte de utilizare."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 4. Costuri și acceptanță"}]},{"type":"paragraph","content":[{"type":"text","text":"Prețurile, moneda, regimul fiscal și recurențele sunt cele individualizate în devizul anexei și în {{payment_terms}}. Criteriile de acceptare, probele necesare și procedura de remediere sunt {{acceptance}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Drepturile asupra livrabilelor urmează {{ip_terms}}, în limitele acordului principal și ale licențelor terților. Anexa produce efecte numai pentru versiunea aprobată de reprezentanții {{signatories}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Condiții specifice și repere de aplicare"}]},{"type":"paragraph","content":[{"type":"text","text":"Anexa identifică versiunea contractului și configurația efectiv acceptată, conform cadrului contractual din Codul civil. Pentru website, software, branding sau produse digitale se enumeră separat fișierele sursă, licențele, materialele terților și utilizările acordate. O extensie de funcționalitate ori o schimbare de licență cere un acord explicit, nu rescrierea unei anexe deja acceptate."}]}]},"fields":{},"labels":{"__avyron_design":"2026","__avyron_edition":"2026-11","__avyron_stage":"3/5","__avyron_legal_review":"2026-11-10"},"lines":[]}','["date","provider.legal_name","provider.tax_id","provider.registration_number","provider.address","provider.registered_address","provider.share_capital","beneficiary.legal_name","scope","beneficiary.entity_type","beneficiary.identification","beneficiary.address","signatories","contract_reference","deliverables","acceptance","schedule","payment_terms","contract_capacity"]','review_required',CAST(strftime('%s','now') AS INTEGER)*1000
