WHERE t.id='access' AND t.visibility='shared' AND v.payload_json='{"title":"Acord de acces și administrare","header":"AVYRON · {{provider.legal_name}}","footer":"{{provider.contact_email}} · Document privat · {{beneficiary.legal_name}}","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Acest acord descrie accesul autorizat pentru activitatea convenită. Drepturile sunt limitate la scopul declarat, se acordă individual și pot fi retrase prin procedura stabilită mai jos."}]},{"type":"paragraph","content":[{"type":"text","text":"Proiect / activitate: {{scope}}. Data documentului: {{date}}."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Emitent AVYRON"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Beneficiar / destinatar"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{provider.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"CUI {{provider.tax_id}} · ONRC {{provider.registration_number}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Sediu: {{provider.address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Capital social: {{provider.share_capital}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Contact: {{provider.contact_email}}"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.summary}}"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Identificarea juridică a beneficiarului: {{beneficiary.identification}}. Sunt utilizate numai datele necesare relației documentate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 1. Mandatul acordat"}]},{"type":"paragraph","content":[{"type":"text","text":"Beneficiarul autorizează persoanele desemnate de {{provider.legal_name}} să efectueze operațiunile {{access_scope}} asupra platformelor {{platforms}}, exclusiv pentru {{scope}}. Identificatorii conturilor și proprietarii lor sunt {{account_references}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Autorizarea este limitată la resursele, acțiunile și durata înscrise. Ea nu conferă dreptul de a transfera proprietatea, a modifica beneficiarii plăților, a accepta costuri sau a șterge definitiv date fără o aprobare distinctă."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 2. Acordarea și protejarea accesului"}]},{"type":"paragraph","content":[{"type":"text","text":"Accesul se acordă prin utilizatori nominali, roluri delegate ori mecanisme OAuth/API cu privilegii minime. Parolele, codurile MFA, cheile private și tokenurile nu se înscriu în document și nu se trimit în canale nesecurizate."}]},{"type":"paragraph","content":[{"type":"text","text":"Responsabilii beneficiarului și ai prestatorului sunt {{contacts}}. Se păstrează evidența acțiunilor relevante și se evită conturile comune atunci când platforma permite conturi individuale."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 3. Operațiuni și responsabilități"}]},{"type":"paragraph","content":[{"type":"text","text":"Publicarea, reclamele, modificările DNS, plățile și schimbările cu impact semnificativ necesită aprobările {{approval_rules}}. Prestatorul comunică erorile și incidentele cunoscute și nu prezintă o configurare drept operațiune finalizată fără dovadă."}]},{"type":"paragraph","content":[{"type":"text","text":"Beneficiarul menține dreptul asupra conturilor și verifică legalitatea materialelor și instrucțiunilor furnizate. Limitările furnizorilor, ferestrele de mesagerie și condițiile platformelor rămân aplicabile."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 4. Durată și revocare"}]},{"type":"paragraph","content":[{"type":"text","text":"Mandatul este valabil pentru {{duration}}. Revocarea și procedura de predare sunt {{revocation}}. La încetare se retrag rolurile și tokenurile relevante, se predau informațiile necesare prin canale securizate și se consemnează rezultatul."}]},{"type":"paragraph","content":[{"type":"text","text":"Obligațiile de confidențialitate și conservare a evidențelor se aplică potrivit acordurilor relevante. Orice extindere de acces sau delegare ulterioară cere autorizare expresă."}]}]},"fields":{},"labels":{"__avyron_design":"2026"},"lines":[]}' AND v.required_fields_json='["date","provider.legal_name","provider.tax_id","provider.registration_number","provider.address","provider.share_capital","beneficiary.legal_name","scope","beneficiary.entity_type","beneficiary.identification","beneficiary.address","signatories","platforms","access_scope","duration","revocation"]'
