SELECT 'privacy_v3_avyron_legal202611',t.id,3,'{"title":"Confidențialitate și protecția datelor","header":"AVYRON · {{provider.legal_name}}","footer":"{{provider.contact_email}} · Document privat · {{beneficiary.legal_name}}","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Acest document stabilește cum sunt utilizate și protejate informațiile schimbate în colaborare. Regimul de prelucrare a datelor se alege după rolurile și operațiunile efective ale părților."}]},{"type":"paragraph","content":[{"type":"text","text":"TRASEU AVYRON · ETAPA 3/5 · Se aleg rolurile reale; confidențialitatea nu activează automat DPA."}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate: {{scope}}. Data: {{date}}."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Emitent AVYRON"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Beneficiar / destinatar"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{provider.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"CUI {{provider.tax_id}} · ONRC {{provider.registration_number}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate / corespondență: {{provider.address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Sediu social: {{provider.registered_address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Capital social: {{provider.share_capital}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Contact: {{provider.contact_email}}"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.summary}}"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Identificarea juridică a beneficiarului: {{beneficiary.identification}}. Sunt utilizate numai datele necesare relației documentate."}]},{"type":"paragraph","content":[{"type":"text","text":"O obligație de confidențialitate nu este, singură, un temei pentru orice utilizare a datelor personale. Scopul, temeiul și responsabilitățile se stabilesc potrivit art. 5–6 GDPR. Listele de clienți, conversațiile, identificatorii și materialele primite nu se reutilizează pentru alte conturi, promovare sau instruire AI fără o bază și o autorizare corespunzătoare."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 1. Scop și alegerea regimului"}]},{"type":"paragraph","content":[{"type":"text","text":"Părțile protejează informațiile schimbate pentru {{scope}}. Regimul selectat este {{privacy_mode}}. Secțiunea privind prelucrarea în numele unui operator se include numai dacă analiza operațiunilor reale o impune și dacă anexele obligatorii sunt completate."}]},{"type":"paragraph","content":[{"type":"text","text":"Sunt confidențiale informațiile identificate ca atare ori care, prin natura și contextul lor, trebuie protejate: {{confidentiality_terms}}. Nu sunt acoperite informațiile devenite publice legal, cunoscute anterior în mod legitim sau obținute independent fără încălcarea unei obligații."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 2. Utilizare și divulgare"}]},{"type":"paragraph","content":[{"type":"text","text":"Informațiile sunt utilizate numai pentru scopul convenit și comunicate persoanelor autorizate care au nevoie de ele și au obligații corespunzătoare de confidențialitate. Măsurile de protecție și canalele permise sunt {{security_measures}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Divulgarea impusă legal se limitează la ceea ce este necesar și este notificată celeilalte părți când legea permite. Durata obligației și procedura de returnare sau ștergere sunt {{duration}} și {{return_deletion}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 3. Roluri și instrucțiuni privind datele"}]},{"type":"paragraph","content":[{"type":"text","text":"Rolurile părților și temeiul relației se stabilesc în {{data_roles}}. Pentru o relație operator–persoană împuternicită conform art. 28 alin. (3) GDPR, obiectul, durata, natura și scopul prelucrării, tipurile de date și categoriile de persoane vizate se descriu în anexa {{processing_annex}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Persoana împuternicită prelucrează datele numai pe baza instrucțiunilor documentate, asigură confidențialitatea persoanelor autorizate și aplică măsurile tehnice și organizatorice convenite. Instrucțiunile considerate contrare normelor aplicabile sunt semnalate operatorului."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 4. Cerințe condiționale pentru acordul de prelucrare"}]},{"type":"paragraph","content":[{"type":"text","text":"Dacă se activează regimul DPA, subîmputerniciții și condițiile autorizării lor, transferurile internaționale și garanțiile aplicabile sunt {{subprocessors_transfers}}, cu verificarea art. 28 și art. 44–49 GDPR. Asistența pentru cereri ale persoanelor vizate, incidente, evaluări și verificări se organizează potrivit {{dpa_assistance}}."}]},{"type":"paragraph","content":[{"type":"text","text":"La încetare, datele sunt returnate sau șterse conform opțiunii documentate și obligațiilor legale de păstrare. Dovezile de conformitate și condițiile auditului sunt {{audit_conditions}}. Această secțiune nu poate fi aprobată fără anexele și verificarea de specialitate necesare."}]}]},"fields":{},"labels":{"__avyron_design":"2026","__avyron_edition":"2026-11","__avyron_stage":"3/5","__avyron_legal_review":"2026-11-10"},"lines":[]}','["date","provider.legal_name","provider.tax_id","provider.registration_number","provider.address","provider.registered_address","provider.share_capital","beneficiary.legal_name","scope","beneficiary.entity_type","beneficiary.identification","beneficiary.address","signatories","confidentiality_terms","duration","privacy_mode"]','review_required',CAST(strftime('%s','now') AS INTEGER)*1000
