SELECT 'implementation_v3_avyron_legal202611',t.id,3,'{"title":"Plan de implementare","header":"AVYRON · {{provider.legal_name}}","footer":"{{provider.contact_email}} · Document privat · {{beneficiary.legal_name}}","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Planul face vizibile etapele, responsabilitățile și punctele de decizie. Fiecare livrabil este legat de un termen, de dependențele sale și de dovada necesară finalizării."}]},{"type":"paragraph","content":[{"type":"text","text":"TRASEU AVYRON · ETAPA 4/5 · O etapă se închide cu livrabil, probă și aprobare identificabile."}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate: {{scope}}. Data: {{date}}."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Emitent AVYRON"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Beneficiar / destinatar"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{provider.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"CUI {{provider.tax_id}} · ONRC {{provider.registration_number}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate / corespondență: {{provider.address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Sediu social: {{provider.registered_address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Capital social: {{provider.share_capital}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Contact: {{provider.contact_email}}"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.summary}}"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Obiectiv și perimetru"}]},{"type":"paragraph","content":[{"type":"text","text":"Planul organizează realizarea {{scope}} și urmărește {{objectives}}. Livrabilele asumate în documentele comerciale sunt {{deliverables}}. Planul nu introduce singur servicii ori costuri suplimentare."}]},{"type":"paragraph","content":[{"type":"text","text":"Versiunea de referință a cerințelor și documentelor aprobate: {{contract_reference}}. Elementele excluse: {{exclusions}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Etape și responsabilități"}]},{"type":"paragraph","content":[{"type":"text","text":"Etapele, rezultatul fiecăreia, responsabilii și termenele sunt {{schedule}}. Fiecare etapă are un rezultat verificabil și o condiție explicită de intrare și ieșire. Activitățile paralele sunt permise numai când dependențele o permit."}]},{"type":"paragraph","content":[{"type":"text","text":"Responsabilii pentru accesuri, conținut, implementare, testare și aprobare sunt {{contacts}}. Beneficiarul indică persoana care poate decide asupra modificărilor de scop."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Dependențe și gestionarea schimbărilor"}]},{"type":"paragraph","content":[{"type":"text","text":"Dependențele tehnice și comerciale sunt {{dependencies}}. Riscurile cunoscute și măsurile de reducere sunt {{risks}}. Lipsa unei autorizări sau indisponibilitatea unui furnizor este evidențiată ca blocaj, fără simularea finalizării."}]},{"type":"paragraph","content":[{"type":"text","text":"Schimbările se înregistrează cu motiv, impact, responsabil și aprobarea necesară. Calendarul se actualizează pentru versiunea nouă fără a rescrie istoricul deciziilor anterioare."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Verificare și finalizare"}]},{"type":"paragraph","content":[{"type":"text","text":"Criteriile de finalizare și dovezile cerute sunt {{acceptance}}. Se verifică separat mediul local, preview și producția, precum și funcțiile dependente de furnizori externi."}]},{"type":"paragraph","content":[{"type":"text","text":"Predarea include documentația convenită, evidența limitărilor rămase și pașii de suport. Publicarea în producție, comunicarea externă și operațiunile financiare urmează propriile aprobări."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Condiții specifice și repere de aplicare"}]},{"type":"paragraph","content":[{"type":"text","text":"Punctele de control pentru acces, date, publicare și încasări sunt incluse în calendar. Protecția datelor prin proiectare și securitatea, când sunt incidente, se urmăresc potrivit art. 25 și 32 GDPR. Activarea unui furnizor, a unei integrări ori a unui cost extern se confirmă distinct de dezvoltarea locală; responsabilul și dovada se consemnează în plan."}]}]},"fields":{},"labels":{"__avyron_design":"2026","__avyron_edition":"2026-11","__avyron_stage":"4/5","__avyron_legal_review":"2026-11-10"},"lines":[]}','["date","provider.legal_name","provider.tax_id","provider.registration_number","provider.address","provider.registered_address","provider.share_capital","beneficiary.legal_name","scope","deliverables","schedule","dependencies","acceptance"]','review_required',CAST(strftime('%s','now') AS INTEGER)*1000
