SELECT 'report_v3_avyron_legal202611',t.id,3,'{"title":"Raport universal","header":"AVYRON · {{provider.legal_name}}","footer":"{{provider.contact_email}} · Document privat · {{beneficiary.legal_name}}","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Raportul reunește activitățile efectuate, rezultatele observate și prioritățile perioadei următoare. Concluziile sunt susținute de sursele și limitele de măsurare indicate în document."}]},{"type":"paragraph","content":[{"type":"text","text":"TRASEU AVYRON · ETAPA 4/5 · Raportăm rezultate observate, surse și limite de măsurare."}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate: {{scope}}. Data: {{date}}."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Emitent AVYRON"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Beneficiar / destinatar"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{provider.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"CUI {{provider.tax_id}} · ONRC {{provider.registration_number}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate / corespondență: {{provider.address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Sediu social: {{provider.registered_address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Capital social: {{provider.share_capital}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Contact: {{provider.contact_email}}"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.summary}}"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"1. Perioadă și obiect"}]},{"type":"paragraph","content":[{"type":"text","text":"Raportul acoperă {{period}} pentru {{scope}} și se raportează la obiectivele {{objectives}}. Tipul de raport și sursele utilizate: {{report_type}} și {{data_sources}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Sunt separate activitățile executate, rezultatele observate și acțiunile propuse. Configurarea unui serviciu sau pregătirea unei operațiuni nu este prezentată drept livrare finală."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"2. Activități și livrabile"}]},{"type":"paragraph","content":[{"type":"text","text":"Activitățile efectuate și starea fiecăreia: {{activities}}. Livrabilele și versiunile la care se referă raportul: {{deliverables}}. Responsabilii și intervențiile beneficiarului: {{contacts}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Pentru campanii, costul media se distinge de onorariu; pentru mentenanță, monitorizarea se distinge de intervenția efectivă; pentru agenți AI, propunerile se disting de acțiunile aprobate și executate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"3. Rezultate și dovezi"}]},{"type":"paragraph","content":[{"type":"text","text":"Indicatorii, metodologia de calcul și comparațiile relevante sunt {{metrics}}. Dovezile verificabile, mediul și momentul observației: {{evidence}}. Constatările și incidentele: {{findings}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Datele indisponibile nu sunt înlocuite cu estimări prezentate ca fapte. Scorurile automate, atribuirea conversiilor și măsurătorile punctuale se interpretează în limitele surselor și perioadei analizate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"4. Recomandări și următorii pași"}]},{"type":"paragraph","content":[{"type":"text","text":"Prioritățile recomandate și justificarea lor sunt {{recommendations}}. Dependențele și aprobările necesare: {{dependencies}}. Activitățile rămase și calendarul propus: {{schedule}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Raportul este verificat înainte de publicare. Rezultatele sunt valabile în contextul descris și nu constituie o promisiune privind poziționări, vânzări, disponibilitate ori absența totală a incidentelor viitoare."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Condiții specifice și repere de aplicare"}]},{"type":"paragraph","content":[{"type":"text","text":"Rapoartele de SEO, Ads, social media, AI, QA și mentenanță identifică intervalul, contul, sursa și metoda indicatorilor. Bugetul media, costul instrumentelor și onorariul se citesc separat. Capturile și exemplele sunt minimizate sau anonimizate, în acord cu art. 5 GDPR; raportul nu transformă accesul tehnic într-un drept de publicare a datelor clientului."}]}]},"fields":{},"labels":{"__avyron_design":"2026","__avyron_edition":"2026-11","__avyron_stage":"4/5","__avyron_legal_review":"2026-11-10"},"lines":[]}','["date","provider.legal_name","provider.tax_id","provider.registration_number","provider.address","provider.registered_address","provider.share_capital","beneficiary.legal_name","scope","period","activities","evidence","findings","recommendations"]','review_required',CAST(strftime('%s','now') AS INTEGER)*1000
