SELECT 'handover_v3_avyron_legal202611',t.id,3,'{"title":"Proces-verbal de recepție și predare","header":"AVYRON · {{provider.legal_name}}","footer":"{{provider.contact_email}} · Document privat · {{beneficiary.legal_name}}","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Părțile consemnează ce a fost predat, ce s-a verificat și ce observații rămân de soluționat. Inventarul și rezultatul recepției permit urmărirea clară a responsabilităților ulterioare."}]},{"type":"paragraph","content":[{"type":"text","text":"TRASEU AVYRON · ETAPA 4/5 · Inventarul și observațiile se confirmă pe versiunea predată."}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate: {{scope}}. Data: {{date}}."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Emitent AVYRON"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Beneficiar / destinatar"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{provider.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"CUI {{provider.tax_id}} · ONRC {{provider.registration_number}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate / corespondență: {{provider.address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Sediu social: {{provider.registered_address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Capital social: {{provider.share_capital}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Contact: {{provider.contact_email}}"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.summary}}"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Identificarea juridică a beneficiarului: {{beneficiary.identification}}. Sunt utilizate numai datele necesare relației documentate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 1. Obiectul predării"}]},{"type":"paragraph","content":[{"type":"text","text":"Părțile consemnează predarea {{scope}}, aferentă acordului {{contract_reference}}, pentru proiectele și serviciile asociate explicit documentului. Livrabilele, versiunile, mediile și formatele predate: {{deliverables}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Data predării și participanții sunt {{date}} și {{signatories}}. Documentul se referă exclusiv la elementele inventariate, fără a presupune acceptarea altor lucrări."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 2. Verificări și rezultat"}]},{"type":"paragraph","content":[{"type":"text","text":"Verificările efectuate, criteriile aplicate și dovezile sunt {{evidence}}. Rezultatul recepției este {{acceptance}}. Se disting elementele acceptate, cele acceptate cu observații și cele pentru care recepția se amână."}]},{"type":"paragraph","content":[{"type":"text","text":"Observațiile și neconformitățile identificate: {{observations}}. Măsurile de remediere, responsabilii și termenele confirmate: {{remediation}}. Funcționalitățile suplimentare solicitate ulterior se tratează separat."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 3. Accesuri și documentație"}]},{"type":"paragraph","content":[{"type":"text","text":"Conturile, rolurile, domeniile, depozitele și documentația predate sunt inventariate prin referințe în {{access_inventory}}. Accesurile sunt transferate prin {{secure_channel}}, fără parole, tokenuri, coduri MFA sau chei private înscrise în acest proces-verbal."}]},{"type":"paragraph","content":[{"type":"text","text":"Drepturile de proprietate intelectuală și licențele rămân cele din documentele aprobate: {{ip_terms}}. Predarea accesului tehnic nu conferă automat drepturi suplimentare asupra produselor ori componentelor terților."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 4. Efecte și suport ulterior"}]},{"type":"paragraph","content":[{"type":"text","text":"Efectele recepției asupra plăților și începutului mentenanței sunt {{handover_effects}}. Serviciile de suport ulterioare se acordă potrivit {{support_reference}} și nu se presupun nelimitate."}]},{"type":"paragraph","content":[{"type":"text","text":"Fiecare parte verifică exactitatea inventarului și păstrează versiunea aprobată. Corecturile ulterioare se consemnează într-un document nou, fără suprascrierea prezentului proces-verbal."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Condiții specifice și repere de aplicare"}]},{"type":"paragraph","content":[{"type":"text","text":"Recepția se raportează la criteriile convenite și nu șterge drepturile ori remediile legale imperative. Licențele și eventualele cesiuni rămân cele documentate în scris; predarea unui fișier sau a unui cont nu extinde singură drepturile. Accesurile nominale se verifică, iar autorizările temporare ale echipei se retrag sau se păstrează numai potrivit mandatului de suport."}]}]},"fields":{},"labels":{"__avyron_design":"2026","__avyron_edition":"2026-11","__avyron_stage":"4/5","__avyron_legal_review":"2026-11-10"},"lines":[]}','["date","provider.legal_name","provider.tax_id","provider.registration_number","provider.address","provider.registered_address","provider.share_capital","beneficiary.legal_name","scope","beneficiary.entity_type","beneficiary.identification","beneficiary.address","signatories","contract_reference","deliverables","evidence","acceptance","observations"]','review_required',CAST(strftime('%s','now') AS INTEGER)*1000
