SELECT 'sla_v3_avyron_legal202611',t.id,3,'{"title":"Acord mentenanță / SLA","header":"AVYRON · {{provider.legal_name}}","footer":"{{provider.contact_email}} · Document privat · {{beneficiary.legal_name}}","body":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Acest acord clarifică resursele protejate, intervențiile incluse și modul de solicitare a suportului. Nivelurile de serviciu, backupul și costurile sunt delimitate explicit, fără acoperire implicit nelimitată."}]},{"type":"paragraph","content":[{"type":"text","text":"TRASEU AVYRON · ETAPA 5/5 · Se confirmă acoperirea, facturarea și limitele reînnoirii."}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate: {{scope}}. Data: {{date}}."}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Emitent AVYRON"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Beneficiar / destinatar"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{provider.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"CUI {{provider.tax_id}} · ONRC {{provider.registration_number}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Activitate / corespondență: {{provider.address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Sediu social: {{provider.registered_address}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Capital social: {{provider.share_capital}}"}]},{"type":"paragraph","content":[{"type":"text","text":"Contact: {{provider.contact_email}}"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.legal_name}}"}]},{"type":"paragraph","content":[{"type":"text","text":"{{beneficiary.summary}}"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Calitatea beneficiarului în această relație: {{contract_capacity}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Identificarea juridică a beneficiarului: {{beneficiary.identification}}. Sunt utilizate numai datele necesare relației documentate."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 1. Serviciile acoperite"}]},{"type":"paragraph","content":[{"type":"text","text":"Acordul privește {{scope}} și resursele inventariate în {{coverage}}. Sunt incluse intervențiile, actualizările și monitorizarea descrise expres. Funcțiile noi, refacerile majore și resursele terților sunt excluse dacă nu sunt înscrise separat."}]},{"type":"paragraph","content":[{"type":"text","text":"Limitele de volum, timp ori număr de intervenții sunt {{service_limits}}. Nu există un nivel de disponibilitate sau suport permanent implicit."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 2. Solicitări și niveluri de suport"}]},{"type":"paragraph","content":[{"type":"text","text":"Canalele, programul de suport, clasificarea incidentelor și țintele de răspuns/remediere sunt {{support_levels}}. Timpul de răspuns se distinge de timpul de soluționare. Persoanele autorizate să solicite intervenții: {{contacts}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Țintele se calculează conform metodei {{measurement_method}}, ținând cont de dependențe și de perioadele excluse convenite. Indisponibilitatea furnizorilor se raportează distinct."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 3. Actualizări și schimbări"}]},{"type":"paragraph","content":[{"type":"text","text":"Actualizările se evaluează în raport cu compatibilitatea, securitatea și impactul. Ferestrele de mentenanță și aprobările sunt {{maintenance_windows}}. Schimbările cu risc semnificativ presupun o procedură de revenire documentată."}]},{"type":"paragraph","content":[{"type":"text","text":"Beneficiarul menține accesurile necesare și comunică modificările făcute de terți. O intervenție care depășește scopul se estimează și se aprobă separat înainte de executare."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 4. Backup și restaurare"}]},{"type":"paragraph","content":[{"type":"text","text":"Ce se salvează, frecvența, destinația privată, retenția și excluderile sunt {{backup_policy}}. Protecția bazei de date se distinge de copia fișierelor și de configurațiile furnizorilor."}]},{"type":"paragraph","content":[{"type":"text","text":"Procedura de restaurare, responsabilitățile, țintele confirmate și verificările periodice sunt {{restore_policy}}. Un backup nu este considerat verificat numai pentru că operațiunea de creare a răspuns fără eroare. Costurile și limitele de stocare sunt {{storage_terms}}."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Art. 5. Durată, tarife și încetare"}]},{"type":"paragraph","content":[{"type":"text","text":"Durata este {{duration}}, tarifele și condițiile de plată sunt {{payment_terms}}, iar regimul fiscal este {{tax_regime}}. Reînnoirea și notificările sunt {{renewal_terms}}."}]},{"type":"paragraph","content":[{"type":"text","text":"Suspendarea, încetarea, exportul datelor și predarea accesurilor sunt {{termination_terms}}. Răspunderea și eventualele compensații de serviciu sunt {{liability_terms}}, în limitele normelor aplicabile și ale acordului principal."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Condiții specifice și repere de aplicare"}]},{"type":"paragraph","content":[{"type":"text","text":"Procedura de incident distinge disponibilitatea, recuperarea și notificările privind datele personale. Pentru o relație de împuternicire se respectă art. 33 alin. (2) GDPR; nu se promite un termen universal care înlocuiește analiza incidentului. Restaurarea este verificată prin probe, inclusiv fișiere și baze de date."}]},{"type":"paragraph","content":[{"type":"text","text":"Reînnoirea, suspendarea și debitarea automată sunt explicite. Acceptarea condițiilor comerciale și autorizarea cardului sunt operațiuni distincte; o factură, un card salvat ori tăcerea clientului nu sunt prezentate drept mandat de debitare. Clauzele neuzuale se verifică potrivit art. 1203 Cod civil."}]}]},"fields":{},"labels":{"__avyron_design":"2026","__avyron_edition":"2026-11","__avyron_stage":"5/5","__avyron_legal_review":"2026-11-10"},"lines":[]}','["date","provider.legal_name","provider.tax_id","provider.registration_number","provider.address","provider.registered_address","provider.share_capital","beneficiary.legal_name","scope","beneficiary.entity_type","beneficiary.identification","beneficiary.address","signatories","coverage","support_levels","backup_policy","restore_policy","duration","payment_terms","renewal_terms","contract_capacity"]','review_required',CAST(strftime('%s','now') AS INTEGER)*1000
